<script setup>
import { onMounted, reactive, ref } from 'vue';import { ElMessage } from 'element-plus';import { createDeadline,listDeadlines,completeDeadline } from '../../api/deadline';import { session } from '../../utils/session';import { options,text,formatDate,tagType } from '../../utils/enums';import PageHeader from '../../components/PageHeader.vue';import AppPagination from '../../components/AppPagination.vue';import { messageOf } from '../../utils/request'
const state=reactive({list:[],total:0,pageNum:1,pageSize:10,status:'',upcoming:false,loading:false});const open=ref(false);const form=reactive({caseId:null,deadlineType:'RESPONSE',taskName:'',officialDeadline:'',internalDeadline:'',priority:'MEDIUM',description:''})
const load=async()=>{state.loading=true;try{const r=await listDeadlines({pageNum:state.pageNum,pageSize:state.pageSize,status:state.status||undefined,upcoming:state.upcoming});state.list=r.data.list;state.total=r.data.total}finally{state.loading=false}}
const complete=async(id)=>{await completeDeadline(id);ElMessage.success('任务已完成');load()};const save=async()=>{try{await createDeadline({...form,internalDeadline:form.internalDeadline||undefined});open.value=false;ElMessage.success('时限已创建');load()}catch(e){ElMessage.error(messageOf(e))}};onMounted(load)
</script>
<template><div class="page"><PageHeader title="时限任务" description="跟踪官方期限和内部办理节点"><el-button type="primary" @click="open=true">新建时限</el-button></PageHeader><div class="toolbar"><div class="filters"><el-select v-model="state.status" placeholder="任务状态" clearable @change="load"><el-option v-for="o in options('deadlineStatus')" :key="o.value" v-bind="o"/></el-select><el-checkbox v-model="state.upcoming" @change="load">仅看 7 天内到期</el-checkbox></div></div><div class="table-wrap"><el-table v-loading="state.loading" :data="state.list"><el-table-column prop="taskName" label="任务名称" min-width="200"/><el-table-column prop="caseId" label="案件 ID" width="90"/><el-table-column prop="deadlineType" label="类型"/><el-table-column label="官方期限" width="155"><template #default="{row}">{{formatDate(row.officialDeadline)}}</template></el-table-column><el-table-column label="优先级" width="90"><template #default="{row}"><el-tag :type="tagType(row.priority)">{{text('priority',row.priority)}}</el-tag></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="tagType(row.status)">{{text('deadlineStatus',row.status)}}</el-tag></template></el-table-column><el-table-column width="80"><template #default="{row}"><el-button v-if="row.status!=='COMPLETED'" link type="success" @click="complete(row.id)">完成</el-button></template></el-table-column></el-table></div><AppPagination v-model:page="state.pageNum" v-model:size="state.pageSize" :total="state.total" @change="load"/><el-dialog v-model="open" title="新建时限任务" width="min(580px,94vw)"><el-form class="form-grid" label-position="top"><el-form-item label="案件 ID"><el-input-number v-model="form.caseId" :min="1"/></el-form-item><el-form-item label="时限类型"><el-input v-model="form.deadlineType"/></el-form-item><el-form-item class="span-2" label="任务名称"><el-input v-model="form.taskName"/></el-form-item><el-form-item label="官方期限"><el-date-picker v-model="form.officialDeadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="内部期限"><el-date-picker v-model="form.internalDeadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="优先级"><el-select v-model="form.priority"><el-option v-for="o in options('priority')" :key="o.value" v-bind="o"/></el-select></el-form-item><el-form-item label="说明"><el-input v-model="form.description"/></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
